import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V2 {

    private static final boolean DEBUG = false;
    private static BufferedWriter writer;
    private static Reader reader;

    private static void log(Object o) {
        if (DEBUG) System.err.println(o);
    }

    private static void println(Object o) {
        System.out.println(o);
    }

    private static void print(Object o) {
        try {
            writer.write(o.toString());
        } catch (IOException ignored) {}
    }

    private static long modExp(long base, long exp, long mod) {
        base %= mod;
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    private static void compute() throws IOException {
        writer = new BufferedWriter(new OutputStreamWriter(System.out));
        reader = new Reader(System.in);

        long n = reader.nextLong();
        long m = reader.nextLong();
        int L = reader.nextInt();
        int R = reader.nextInt();

        long MOD = 998244353L;
        long total = n * m;
        long inv2 = modExp(2, MOD - 2, MOD);

        long rangeSize = R - L + 1;
        long odds = rangeSize / 2;
        long evens = rangeSize - odds;

        long result;
        if (total % 2 == 1) {
            result = modExp(rangeSize, total, MOD);
        } else {
            long t1 = modExp(rangeSize, total, MOD);
            long t2 = modExp(Math.abs(evens - odds), total, MOD);
            result = (t1 + t2) % MOD;
            result = (result * inv2) % MOD;
        }

        print(result + "\n");
        writer.flush();
        writer.close();
    }

    public static void main(String[] args) throws IOException {
        compute();
    }

    static class Reader {
        private final InputStream input;
        private final byte[] buffer = new byte[8192];
        private int pos = 0, count = 0;

        Reader(InputStream stream) {
            input = stream;
        }

        private int next() throws IOException {
            if (pos >= count) {
                pos = 0;
                count = input.read(buffer);
                if (count <= 0) return -1;
            }
            return buffer[pos++];
        }

        private void skip() throws IOException {
            int c;
            while ((c = next()) != -1 && c <= 32) {}
            pos--;
        }

        public int nextInt() throws IOException {
            skip();
            boolean neg = false;
            int c = next();
            if (c == '-') {
                neg = true;
                c = next();
            }
            int num = 0;
            while (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
                c = next();
            }
            return neg ? -num : num;
        }

        public long nextLong() throws IOException {
            skip();
            boolean neg = false;
            int c = next();
